create table public.capcat_profiles (id uuid primary key default auth.uid() references auth.users(id), name text not null check (char_length(trim(name)) between 1 and 40), avatar_path text, created_at timestamptz not null default now());
create table public.capcat_cats (id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references public.capcat_profiles(id), name text not null check (char_length(trim(name)) between 1 and 40), description text check (char_length(description) <= 250), photo_path text not null, created_at timestamptz not null default now());
create index capcat_cats_owner_idx on public.capcat_cats(owner_id);
create index capcat_cats_date_idx on public.capcat_cats(created_at desc);
alter table public.capcat_profiles enable row level security;
alter table public.capcat_cats enable row level security;
revoke all on public.capcat_profiles, public.capcat_cats from anon;
grant select,insert,update on public.capcat_profiles to authenticated;
grant select,insert,update,delete on public.capcat_cats to authenticated;
create policy capcat_profiles_read on public.capcat_profiles for select to authenticated using (true);
create policy capcat_profiles_insert on public.capcat_profiles for insert to authenticated with check (id = (select auth.uid()));
create policy capcat_profiles_update on public.capcat_profiles for update to authenticated using (id = (select auth.uid())) with check (id = (select auth.uid()));
create policy capcat_cats_read on public.capcat_cats for select to authenticated using (true);
create policy capcat_cats_insert on public.capcat_cats for insert to authenticated with check (owner_id = (select auth.uid()) and split_part(photo_path,'/',1) = (select auth.uid())::text);
create policy capcat_cats_update on public.capcat_cats for update to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()) and split_part(photo_path,'/',1) = (select auth.uid())::text);
create policy capcat_cats_delete on public.capcat_cats for delete to authenticated using (owner_id = (select auth.uid()));
insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('capcat-images','capcat-images',false,10485760,array['image/jpeg','image/png','image/webp']);
create policy capcat_images_read on storage.objects for select to authenticated using (bucket_id = 'capcat-images');
create policy capcat_images_insert on storage.objects for insert to authenticated with check (bucket_id = 'capcat-images' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy capcat_images_update on storage.objects for update to authenticated using (bucket_id = 'capcat-images' and owner_id = (select auth.uid())::text) with check (bucket_id = 'capcat-images' and owner_id = (select auth.uid())::text and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy capcat_images_delete on storage.objects for delete to authenticated using (bucket_id = 'capcat-images' and owner_id = (select auth.uid())::text);
